end

function OverseaManageCookingListPopupDialog:RefreshUI(params)
    MaidCoffeeUtils.PlayMusicById(MaidCoffeeConstants.MaidCoffeeMusicName.RecipeLevelUp)
    cs_coroutine.start(function()
        CS.Engine.UI.UIRaycastBlocker.Instance:AddCondition("OverseaManageCookingListPopupDialog")
        local data = params.data
        if data then
            local foodVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.foodId)
            if not isNull(foodVo) then
                CfUtils.FillText(self.TxtIconName,foodVo.name)
                CfUtils.FillImage(self.ImgIconFood.gameObject,foodVo.photoPath)
                local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
                local recipeDojo = maidCoffeePlayerComponent:GetRecipeDoJoById(data.refId)

                CfUtils.SetUISwitchImage(self.ImgLevelBefore,params.oldRating)
                CfUtils.SetUISwitchImage(self.ImgLevelAfter,recipeDojo.rating)

                CfUtils.FillText(self.TxtNmber2,data:GetPrice(recipeDojo.rating))
                CfUtils.FillText(self.TxtNmber1,data:GetPrice(params.oldRating))
                local MaidCoffeeUtils     = import("Game.MaidCoffee.MaidCoffeeUtils")
                local goodsId = MaidCoffeeUtils.GetMaidCoffeeManagerSettingVo(7).num
                ---@type GoodsVo
                local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
                if goodsVo then
                    CfUtils.FillImage(self.ImgIcon1,goodsVo.photoPath)
                    CfUtils.FillImage(self.ImgIcon2,goodsVo.photoPath)
                end
            end
        end
        coroutine.yield( CS.Engine.Lib.Yielders.GetWaitForSeconds(0.7))
        CS.Engine.UI.UIRaycastBlocker.Instance:RemoveCondition("OverseaManageCookingListPopupDialog")
    end)
end

function OverseaManageCookingListPopupDialog:Start()
end

function OverseaManageCookingListPopupDialog:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return OverseaManageCookingListPopupDialog